  "track.animation.m.aas.s.intro.same.explain": "Giá trị đã ở 100; composable chạy lại vì một state khác, target vẫn 100.",
  "track.animation.m.aas.ev.intro.same": "Recompose vì lý do khác",
  "track.animation.m.aas.s.create.title": "remember tạo AnimateAsState",
  "track.animation.m.aas.s.create.explain": "`remember { AnimateAsState(target, …) }` tạo một `Animatable(0f)`; khối remember đặt `updating = false`, nên lần đầu KHÔNG có `SideEffect`, không có animation: giá trị bắt đầu đúng bằng target.",
  "track.animation.m.aas.ev.create": "remember tạo AnimateAsState",
  "track.animation.m.aas.s.read.title": "Đọc state.value",
  "track.animation.m.aas.s.read.explain": "Giá trị trả về là `State<Float>`; đọc nó là đọc `animatable.value` (qua `asState()`), một snapshot state.",
  "track.animation.m.aas.ev.read": "Đọc state.value",
