  "track.animation.m.aas.ev.end.first": "Kết thúc: không job nào",
  "track.animation.m.aas.s.recompose.title": "Recompose với target 100 → SideEffect gọi update()",
  "track.animation.m.aas.s.recompose.explain": "Sau khi composition apply, `SideEffect` gọi `state.update(100f, …)`. Vì 100 khác `animatable.targetValue` (0), cần chạy lại animation.",
  "track.animation.m.aas.ev.recompose": "Recompose với target 100 → SideEffect gọi update()",
  "track.animation.m.aas.s.recomposeSame.title": "Recompose với target 100 như cũ",
  "track.animation.m.aas.s.recomposeSame.explain": "`SideEffect` vẫn gọi `update()` sau mỗi lần recompose.",
  "track.animation.m.aas.ev.recomposeSame": "Recompose với target 100 như cũ",
  "track.animation.m.aas.s.noop.title": "target == targetValue → không làm gì",
  "track.animation.m.aas.s.noop.explain": "Không đổi type converter, không đổi label, target bằng: không restart, không job mới.",
  "track.animation.m.aas.ev.noop": "target == targetValue → không làm gì",
  "track.animation.m.aas.s.end.same.title": "Kết thúc: 0 job",
  "track.animation.m.aas.s.end.same.explain": "Recompose thường xuyên không tự tạo animation mới.",
  "track.animation.m.aas.ev.end.same": "Kết thúc: 0 job",
  "track.animation.m.aas.s.launch.title": "restartAnimation: chạy animateTo(100)",
  "track.animation.m.aas.s.launch.explain": "`job?.cancel()` (chưa có job), rồi `coroutineScope.launch(start = UNDISPATCHED) { animatable.animateTo(100f, spec) }`. Scope đến từ `rememberCoroutineScope()`, nên job sống theo composable (chương EF của Runtime).",
  "track.animation.m.aas.ev.launch": "restartAnimation: chạy animateTo(100)",
  "track.animation.m.aas.s.frame.title": "Frame: giá trị = {v}",
  "track.animation.m.aas.s.frame.explain": "`animateTo` đặt giá trị mới mỗi frame; ai đọc `state.value` trong composition sẽ recompose, đọc trong `graphicsLayer {}` hay `offset {}` thì chỉ layout/draw (C7).",
  "track.animation.m.aas.ev.frame": "Frame: giá trị = {v}",
  "track.animation.m.aas.s.frame2.title": "Frame: giá trị = {v}",
  "track.animation.m.aas.s.frame2.explain": "Spring mới mang theo vận tốc cũ, nên giá trị còn đi lên một chút trước khi quay về 40.",
  "track.animation.m.aas.ev.frame2": "Frame: giá trị = {v}",
  "track.animation.m.aas.s.settle.title": "Animation xong, finishedListener",
  "track.animation.m.aas.s.settle.explain": "Khi `animateTo` trả về, `finishedListener` (nếu có) được gọi với giá trị cuối. Ví dụ dùng nó để in ra màu cuối cùng.",
  "track.animation.m.aas.ev.settle": "Animation xong, finishedListener",
  "track.animation.m.aas.s.end.change.title": "Kết thúc: 1 job, giá trị 100",
  "track.animation.m.aas.s.end.change.explain": "Một lần đổi target, một coroutine.",
  "track.animation.m.aas.ev.end.change": "Kết thúc: 1 job, giá trị 100",
  "track.animation.m.aas.s.retarget.title": "Target đổi sang 40: hủy job cũ, launch job mới",
  "track.animation.m.aas.s.retarget.explain": "`update()` thấy 40 ≠ 100 và `animatable.isRunning`, nên `isInterrupted = true`; `restartAnimation` gọi `job?.cancel()` rồi launch `animateTo(40f)`. Animatable bắt đầu từ giá trị hiện tại (52), không nhảy.",
  "track.animation.m.aas.ev.retarget": "Target đổi sang 40: hủy job cũ, launch job mới",
  "track.animation.m.aas.s.end.interrupt.title": "Kết thúc: 2 job, 1 bị cancel, giá trị 40",
  "track.animation.m.aas.s.end.interrupt.explain": "Bạn không phải viết gì để xử lý việc ngắt.",
  "track.animation.m.aas.ev.end.interrupt": "Kết thúc: 2 job, 1 bị cancel, giá trị 40",
  "track.animation.m.aas.co.noSide": "Mã ở commit ghim có chú thích \"Avoid calling state.update on initial composition\". [[src:an-aas-src]]",
  "track.animation.m.aas.co.same": "`restartAnimation` chỉ được gọi khi converter, label hoặc target đổi. [[src:an-aas-src]]",
  "track.animation.m.aas.co.launch": "Chú thích trong mã: UNDISPATCHED \"to allow for continuous progress when target changes every frame\". [[src:an-aas-src]]",
  "track.animation.m.aas.co.read": "Tài liệu: nếu target đổi khi đang chạy, animate*AsState bắt đầu từ giá trị và vận tốc hiện tại. [[src:an-value]]",
  "track.animation.m.aas.co.velocity": "KDoc: \"the on-going animation will adjust course to animate towards the new target value\". [[src:an-aas-src]] [[src:an-value]]",
  "track.animation.cap.aas": "Từ trái sang phải: composable gọi animate*AsState, đối tượng AnimateAsState được remember, job coroutine, Animatable. Mũi tên vòng về composable là giá trị mới mỗi frame.",
  "track.animation.c1.sim.animation.aas": "Bên trong animate*AsState",
  "track.animation.c1.sim.animation.retarget": "Lab: đổi target",
  "track.animation.c1.quiz.q3.q": "Spec mặc định của animate*AsState là gì?",
  "track.animation.c1.quiz.q3.a": "spring().",
  "track.animation.c1.quiz.q3.why": "KDoc: `animationSpec = remember { spring() }`.",
  "track.animation.c1.quiz.q4.q": "update() được gọi từ đâu?",
  "track.animation.c1.quiz.q4.a": "Từ SideEffect, sau mỗi lần recompose (không ở lần đầu).",
  "track.animation.c1.quiz.q4.why": "Nên nó chạy sau khi composition được apply.",
  "track.animation.m.vector.title": "Spec không biết kiểu: mọi thứ thành AnimationVector",
  "track.animation.m.vector.overview": "Bốn giá trị được animate: một `Dp` với tween, một `Offset` với spring, một `Color` với tween và một `Float` với keyframes. Theo đường đi ở commit ghim: giá trị → `TwoWayConverter` → `AnimationVector` (1–4 chiều) → `VectorizedAnimationSpec` tính từng thành phần theo thời gian → đổi ngược về kiểu cũ.",
  "track.animation.m.vector.wrapup": "`AnimationSpec<T>` chỉ có một việc: `vectorize(converter)` thành một `VectorizedAnimationSpec<V>` làm việc trên vector số thực. Vì vậy cùng một `tween` dùng được cho Dp, Offset, Color hay kiểu của riêng bạn, miễn là có converter.\nMàu được animate trong không gian màu Oklab (bốn chiều: alpha, L, a, b), không phải RGB. Nhờ vậy đi từ đỏ sang trắng không phải đi qua những màu xỉn ở giữa.\nQuy tắc dễ nhớ: spec chỉ biết số; converter lo đổi kiểu của bạn thành số và ngược lại.",
  "track.animation.m.vector.simp.1": "Giá trị giữa chừng: Dp và Color tính theo FastOutSlowIn tại 150/300 ms (fraction ≈ 0.776); Offset (spring) là số minh họa; keyframes nội suy tuyến tính (LinearEasing mặc định giữa các mốc).",
  "track.animation.m.vector.simp.2": "Toạ độ Oklab của đỏ và trắng tính theo công thức chuẩn của Oklab với sRGB; bộ chuyển đổi thật còn kẹp giá trị và đổi về color space đích.",
  "track.animation.m.vector.ctl.hint": "Đổi kiểu giá trị và xem số chiều của vector.",
